mapper.select:
SELECT X.TARGET_CD, X.TARGET_SQ, X.CONTENT, DATE_FORMAT(X.REG_DT, '%m-%d %H:%i') AS REG_DT , (SELECT E.EMPLY_NM FROM TB_EEP_EMPLY_M E WHERE E.EMPLY_ID = X.EMPLY_ID LIMIT 1) AS EMPLY_NM , CASE X.TARGET_CD WHEN 'STAFF' THEN (SELECT S.STAFF_NM FROM TB_EEP_HR_STAFF_M S WHERE S.STAFF_SQ = X.TARGET_SQ) WHEN 'DEPLOY' THEN (SELECT S.STAFF_NM FROM TB_EEP_HR_STAFF_M S WHERE S.STAFF_SQ = X.TARGET_SQ) WHEN 'INTV' THEN (SELECT I.APLY_NM FROM TB_EEP_HR_INTV_M I WHERE I.INTV_SQ = X.TARGET_SQ) WHEN 'TRAINEE' THEN (SELECT T.TRN_NM FROM TB_EEP_HR_TRAINEE_M T WHERE T.TRN_SQ = X.TARGET_SQ) WHEN 'EQP' THEN (SELECT Q.EQP_NO FROM TB_EEP_EQP_M Q WHERE Q.EQP_SQ = X.TARGET_SQ) WHEN 'LAB_TEAM' THEN (SELECT L.TEAM_NM FROM TB_EEP_LAB_TEAM_M L WHERE L.TEAM_SQ = X.TARGET_SQ) END AS TARGET_NM FROM ( SELECT M.MEMO_SQ, M.TARGET_CD, M.TARGET_SQ, M.CONTENT, M.EMPLY_ID, M.REG_DT FROM TB_EEP_ROW_MEMO_R M WHERE M.EMPLY_ID <> 'MIGRATED' AND M.TARGET_CD IN #{t}
UNION ALL SELECT D.MEMO_SQ, 'DEPLOY', D.STAFF_SQ, D.CONTENT, D.EMPLY_ID, D.REG_DT FROM TB_EEP_DEPLOY_MEMO_R D
) X ORDER BY X.REG_DT DESC LIMIT 20
